(() => {
  // 自动定位主酒馆窗口（兼容 iframe 沙箱）
  let W = window;
  try { while (!W.document.getElementById('chat') && W !== W.parent) W = W.parent; } catch (e) {}
  const D = W.document, chat = D.getElementById('chat');
  if (!chat) return console.warn('[批注] 找不到 #chat');

  W.__anno?.();
  D.getElementById('anno-style')?.remove();
  const css = D.createElement('style');
  css.id = 'anno-style';
  css.textContent = `
    .anno{cursor:pointer;border-bottom:1.6px dashed #c9962f;}
    .anno-高燃{border-bottom-color:#d9534f;} .anno-转折{border-bottom-color:#7e6bd6;}
    .anno-pop{position:fixed;z-index:99999;max-width:280px;padding:12px 14px;border-radius:12px;
      background:#fff;color:#222;font-size:13px;line-height:1.7;box-shadow:0 8px 30px rgba(0,0,0,.25);}
    .anno-pop b{color:#c9962f;} .anno-mono{font-style:italic;padding-left:10px;border-left:2px solid #c9962f;}
    .anno-foot{margin-top:8px;font-size:11px;color:#999;text-align:center;}`;
  D.head.appendChild(css);

  const RE = /\[\[(金句|高燃|转折)\]\]([\s\S]*?)\[\[网友\]\]([\s\S]*?)\[\[心声\]\]([\s\S]*?)\[\[\/\]\]/g;
  const ea = s => s.replace(/"/g, '&quot;');
  const scan = () => D.querySelectorAll('#chat .mes_text').forEach(el => {
    if (!el.innerHTML.includes('[[')) return;
    el.innerHTML = el.innerHTML.replace(RE, (_, t, txt, c, m) =>
      `<span class="anno anno-${t}" data-c="${ea(c.trim())}" data-m="${ea(m.trim())}">${txt}</span>`);
  });
  scan();
  const obs = new MutationObserver(() => scan());
  obs.observe(chat, { childList: true, subtree: true });

  const esc = s => s.replace(/[&<>]/g, c => ({ '&':'&amp;','<':'&lt;','>':'&gt;' }[c]));
  let pop = null, cur = null;
  const closePop = () => { pop?.remove(); pop = null; cur = null; };
  const show = (span, view) => {
    closePop();
    pop = D.createElement('div'); pop.className = 'anno-pop';
    if (view === 'c') {
      pop.innerHTML = (span.dataset.c || '').split('｜').map(s =>
        `<div><b>${esc(s.split(/：|:/)[0])}</b>：${esc(s.split(/：|:/).slice(1).join(''))}</div>`).join('')
        + '<div class="anno-foot">再点一下 · 看心声 ↺</div>';
    } else {
      pop.innerHTML = `<div class="anno-mono">${esc(span.dataset.m || '')}</div>`
        + '<div class="anno-foot">再点一下 · 收起</div>';
    }
    D.body.appendChild(pop);
    const r = span.getBoundingClientRect();
    pop.style.left = Math.min(r.left, W.innerWidth - pop.offsetWidth - 8) + 'px';
    pop.style.top = (r.bottom + 8) + 'px';
    cur = { span, view };
  };
  const onClick = (e) => {
    const span = e.target.closest('.anno');
    if (span) {
      e.stopPropagation();
      if (cur?.span !== span) show(span, 'c');
      else if (cur.view === 'c') show(span, 'm');
      else closePop();
    } else if (e.target.closest('.anno-foot') && cur) {
      cur.view === 'c' ? show(cur.span, 'm') : closePop();
    } else if (!e.target.closest('.anno-pop')) closePop();
  };
  D.addEventListener('click', onClick, true);

  W.__anno = () => { obs.disconnect(); D.removeEventListener('click', onClick, true); closePop(); css.remove(); };
})();
